import { escapeHtml as h, number } from './domain.js';
const errorBox='<p class="form-error" role="alert" hidden></p>';
export function clanPanel(clan, clans) {
  if(clan) return `<section class="clan-section" aria-labelledby="clan-title"><div class="eyebrow">ALLÉGEANCE · SESSION ALPHA</div><h3 id="clan-title">Votre clan</h3><div class="clan-standard"><span class="clan-crest" aria-hidden="true">◇</span><div><strong>[${h(clan.name)}]</strong><p>${clan.role==='founder'?'Fondateur':'Membre'} · ${number(clan.member_count)} ${clan.member_count>1?'membres':'membre'}</p></div></div><p>Chaque planète décide de son identité publique. Activez son tag dans la page Planètes, ou gardez votre affiliation masquée.</p><form data-clan-action="leave" data-clan-id="${h(clan.id)}">${errorBox}<button class="secondary" type="submit">Quitter le clan</button><p class="form-note">Vos tags seront masqués. Le fondateur transmet son rôle au membre le plus ancien ; le dernier départ dissout le clan.</p></form></section>`;
  return `<section class="clan-section" aria-labelledby="clan-title"><div class="eyebrow">ALLÉGEANCE · SESSION ALPHA</div><h3 id="clan-title">Votre prochaine alliance</h3><p>Créez votre clan ou rejoignez un clan existant. Un seul clan à la fois ; aucune affiliation n’est affichée automatiquement sur vos planètes.</p><div class="clan-choices"><form data-clan-action="create"><h4>Créer un clan</h4><label class="field">Nom du clan<input name="clan_name" required minlength="3" maxlength="24" placeholder="Ex. Les Veilleurs" autocomplete="off"></label><p class="form-note">3 à 24 caractères. Le nom apparaîtra sous la forme [Nom du clan].</p>${errorBox}<button class="primary" type="submit">Créer mon clan <span aria-hidden="true">→</span></button></form><form data-clan-action="join"><h4>Rejoindre un clan</h4>${clans.length?`<label class="field">Clans de la session<select name="clan_id" required><option value="">Choisir un clan</option>${clans.map(c=>`<option value="${h(c.id)}">${h(c.name)}</option>`).join('')}</select></label><p class="form-note">L’adhésion est libre dans cette première version. Les appartenances des autres joueurs ne sont pas affichées dans l’annuaire.</p>${errorBox}<button class="secondary" type="submit">Rejoindre ce clan</button>`:'<p class="clan-empty">Aucun clan pour le moment.<br>Tracez la première bannière parmi les étoiles.</p>'}</form></div></section>`;
}
export function planetOptions(planet,clan){return `<section class="planet-options" aria-labelledby="planet-options-title"><div><div class="eyebrow">IDENTITÉ & ÉCHANGES</div><h3 id="planet-options-title">Votre monde, votre signature.</h3><p>Le nom de la planète reste inchangé. Le tag reflète uniquement votre choix d’affichage.</p></div><form id="planet-options-form"><label class="option-row"><input name="clan_tag" type="checkbox" ${planet.clan_tag_visible?'checked':''} ${!clan?'disabled':''}><span><strong>Afficher ${clan?`[${h(clan.name)}]`:'mon clan'} sur cette planète</strong><small>${clan?'Le nom et le clan seront visibles sur la carte. Désactivez pour garder ce monde non identifié aux autres joueurs.':'Rejoignez ou créez un clan dans Compte & clan pour activer un tag.'}</small></span></label><label class="option-row"><input name="auto_trade" type="checkbox" ${planet.auto_trade?'checked':''}><span><strong>Commerce automatique</strong><small>Activé par défaut. Désactivez pour examiner les futures demandes avant acceptation.</small></span></label><p class="form-note">La préférence commerciale est sauvegardée ; les liaisons et leurs revenus seront activés avec le système économique.</p>${errorBox}<button class="secondary" type="submit">Enregistrer les options</button></form></section>`;}
